1	use std::hint::black_box;
2	
3	use hdrhistogram::Histogram;
4	
5	use crate::overhead::Overhead;
6	
7	const WARMUP: u64 = 10_000;
8	const ESTIMATE_STEPS: u64 = 1_000;
9	const ESTIMATE_SAMPLES: usize = 5;
10	const FRAMING_DOMINATION_RATIO: f64 = 10.0;
11	const MAX_INNER: u64 = 1_000;
12	
13	pub trait Bench {
14	    fn name(&self) -> &str;
15	    fn step(&mut self) -> u64;
16	}
17	
18	#[derive(Debug)]
19	pub struct RunCfg<'a> {
20	    pub overhead: &'a Overhead,
21	    pub target_seconds: f64,
22	    pub outer_override: Option<u64>,
23	    pub inner_override: Option<u64>,
24	    /// Core pool for thread pinning. Indexed positionally with wrap-around
25	    /// via `core_for(thread_idx)`; empty means no pinning.
26	    pub pin_cores: &'a [usize],
27	}
28	
29	impl RunCfg<'_> {
30	    /// CPU id for the bench's `thread_idx`-th thread, using wrap-around
31	    /// over the pool. Returns `None` when the pool is empty so callers
32	    /// can treat unpinned and pinned runs uniformly.
33	    pub fn core_for(&self, thread_idx: usize) -> Option<usize> {
34	        if self.pin_cores.is_empty() {
35	            None
36	        } else {
37	            Some(self.pin_cores[thread_idx % self.pin_cores.len()])
38	        }
39	    }
40	}
41	
42	pub fn run_adaptive<B: Bench>(bench: &mut B, cfg: &RunCfg) -> (Histogram<u64>, u64, u64, f64) {
43	    for _ in 0..WARMUP {
44	        black_box(bench.step());
45	    }
46	
47	    let step_cost_ns = estimate_step_cost(bench);
48	    let framing_ns = cfg.overhead.framing_per_sample_ns.max(1.0);
49	    let inner = cfg
50	        .inner_override
51	        .unwrap_or_else(|| pick_inner(step_cost_ns, framing_ns));
52	
53	    match cfg.outer_override {
54	        Some(outer) => {
55	            let (hist, duration_s) = run_counted(bench, outer, inner);
56	            (hist, outer, inner, duration_s)
57	        }
58	        None => {
59	            let (hist, duration_s) = run_timed(bench, cfg.target_seconds, inner);
60	            let outer = hist.len();
61	            (hist, outer, inner, duration_s)
62	        }
63	    }
64	}
65	
66	fn estimate_step_cost<B: Bench>(bench: &mut B) -> f64 {
67	    let mut samples: Vec<f64> = (0..ESTIMATE_SAMPLES)
68	        .map(|_| {
69	            let start = minstant::Instant::now();
70	            for _ in 0..ESTIMATE_STEPS {
71	                black_box(bench.step());
72	            }
73	            let total = start.elapsed().as_nanos() as u64;
74	            total as f64 / ESTIMATE_STEPS as f64
75	        })
76	        .collect();
77	    samples.sort_by(|a, b| a.partial_cmp(b).unwrap());
78	    samples[ESTIMATE_SAMPLES / 2]
79	}
80	
81	fn pick_inner(step_cost_ns: f64, framing_ns: f64) -> u64 {
82	    let target = (FRAMING_DOMINATION_RATIO * framing_ns / step_cost_ns).ceil() as u64;
83	    target.clamp(1, MAX_INNER)
84	}
85	
86	fn run_counted<B: Bench>(bench: &mut B, outer: u64, inner: u64) -> (Histogram<u64>, f64) {
87	    let mut hist = new_hist();
88	    let run_start = minstant::Instant::now();
89	    for _ in 0..outer {
90	        record_sample(bench, inner, &mut hist);
91	    }
92	    let duration_s = run_start.elapsed().as_nanos() as f64 / 1e9;
93	    (hist, duration_s)
94	}
95	
96	fn run_timed<B: Bench>(bench: &mut B, target_seconds: f64, inner: u64) -> (Histogram<u64>, f64) {
97	    let mut hist = new_hist();
98	    let target_ns = (target_seconds * 1e9) as u128;
99	    let run_start = minstant::Instant::now();
100	    loop {
101	        record_sample(bench, inner, &mut hist);
102	        if run_start.elapsed().as_nanos() >= target_ns {
103	            break;
104	        }
105	    }
106	    let duration_s = run_start.elapsed().as_nanos() as f64 / 1e9;
107	    (hist, duration_s)
108	}
109	
110	fn new_hist() -> Histogram<u64> {
111	    // 1 ns to 60 s, 3 sig figs
112	    Histogram::<u64>::new_with_bounds(1, 60_000_000_000, 3).unwrap()
113	}
114	
115	fn record_sample<B: Bench>(bench: &mut B, inner: u64, hist: &mut Histogram<u64>) {
116	    let start = minstant::Instant::now();
117	    for _ in 0..inner {
118	        black_box(bench.step());
119	    }
120	    let elapsed_ns = start.elapsed().as_nanos() as u64;
121	    hist.record(round_elapsed(elapsed_ns, inner)).unwrap();
122	}
123	
124	fn round_elapsed(elapsed_ns: u64, inner: u64) -> u64 {
125	    (elapsed_ns + inner / 2) / inner
126	}
127	
128	pub fn fmt_commas(n: u64) -> String {
129	    let s = n.to_string();
130	    let mut result = String::new();
131	    for (i, c) in s.chars().rev().enumerate() {
132	        if i > 0 && i % 3 == 0 {
133	            result.push(',');
134	        }
135	        result.push(c);
136	    }
137	    result.chars().rev().collect()
138	}
139	
140	pub fn fmt_commas_f64(n: f64, decimals: usize) -> String {
141	    let s = format!("{n:.decimals$}");
142	    let (sign, body) = match s.strip_prefix('-') {
143	        Some(rest) => ("-", rest),
144	        None => ("", s.as_str()),
145	    };
146	    let (int_part, frac_part) = match body.find('.') {
147	        Some(i) => (&body[..i], &body[i..]),
148	        None => (body, ""),
149	    };
150	    let int_num: u64 = int_part.parse().unwrap_or(0);
151	    format!("{sign}{}{frac_part}", fmt_commas(int_num))
152	}
153	
154	pub fn print_histogram(
155	    name: &str,
156	    outer: u64,
157	    inner: u64,
158	    duration_s: f64,
159	    hist: &Histogram<u64>,
160	    overhead: &Overhead,
161	) {
162	    // Header line: bench name + logfmt-style metadata. `adj` is the
163	    // apparatus overhead subtracted from each sample downstream.
164	    let adj = overhead.per_call_ns(inner);
165	    let total = outer * inner;
166	    println!(
167	        "{name} [duration={:.1}s outer={} inner={} calls={} adj/call={}ns]:",
168	        duration_s,
169	        fmt_commas(outer),
170	        inner,
171	        fmt_commas(total),
172	        fmt_commas_f64(adj, 2),
173	    );
174	
175	    // Band boundaries defined by percentiles. Each consecutive pair
176	    // forms one band; we iterate the histogram to compute per-band
177	    // stats (first, last, count, mean).
178	    let boundary_pcts: &[f64] = &[
179	        0.0, 0.01, 0.10, 0.20, 0.30, 0.40, 0.50, 0.60, 0.70, 0.80, 0.90, 0.99, 1.0,
180	    ];
181	    let boundary_names: &[&str] = &[
182	        "min", "p1", "p10", "p20", "p30", "p40", "p50", "p60", "p70", "p80", "p90", "p99", "max",
183	    ];
184	
185	    let n_bands = boundary_pcts.len() - 1;
